INSERT INTO "public"."lessons" ("id", "title", "description", "pillar_id", "difficulty", "xp_reward", "content", "image_url", "audio_url", "estimated_duration", "is_active", "sort_order", "created_at", "updated_at", "audio_assets", "visual_assets", "interactive_config", "lesson_code", "unit_number", "lesson_number", "level_name", "description_pt", "under_construction", "target_audience", "is_preview", "edition", "skill_axes") VALUES ('d2f55a9c-6ac6-4276-b5a2-2a67d22b3911', '1. The Pitch', null, 101, 'Beginner', 100, '{"type":"multi_step","unit":1,"steps":[{"id":"step-1","type":"scenario","title":"1. The Pitch","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/vocab/word-st5-pitch.png"},{"id":"step-2","type":"vocabulary","title":"The playing surface","content":"Every football pitch in the world has the same lines and areas. Learn them once — from Old Trafford to the local park, they''re always in the same place.","vocabulary":[{"english":"pitch","example":"The pitch is bright green under the lights.","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/wc/vocabulary/pitch.m4a.mp4","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/vocab/word-st5-pitch.png","usage_tip":"British and Brazilian fans say ''pitch''. Americans say ''field''. Both are understood.","translation":"campo","pronunciation":"/pɪtʃ/"},{"english":"ball","example":"He kicks the ball into the top corner.","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/wc/vocabulary/ball.m4a.mp4","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/vocab/word-st5-ball.png","usage_tip":"The most important object in the game.","translation":"bola","pronunciation":"/bɔːl/"}]},{"id":"step-3","type":"vocabulary","title":"Parts of the pitch","content":"The three most important zones on the pitch. Learn these — every match commentary is built on them.","vocabulary":[{"english":"penalty area","example":"He was fouled inside the penalty area.","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/wc/vocabulary/pitch/penalty-area.m4a.mp4","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/vocab/penalty-area.png","usage_tip":"The big rectangle in front of goal. Fans also call it ''the box''. A foul here by a defender = penalty kick.","translation":"grande área","pronunciation":"/ˈpɛnəlti ˈɛəriə/"},{"english":"halfway line","example":"The match starts with a kick-off on the halfway line.","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/wc/vocabulary/pitch/halfway-line.m4a.mp4","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/vocab/halfway-line.png","usage_tip":"The line across the middle that divides the pitch in two. Your half, their half.","translation":"linha do meio-campo","pronunciation":"/ˈhɑːfweɪ laɪn/"},{"english":"corner","example":"England won a corner in the last minute.","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/wc/vocabulary/pitch/corner.m4a.mp4","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/vocab/corner.png","usage_tip":"The four corners of the pitch. Also short for ''corner kick'' — the set-piece from that spot.","translation":"escanteio","pronunciation":"/ˈkɔːnə/"}]},{"id":"step-4","type":"drag_drop_vocab","title":"Match the word to the picture","content":"Drag each English word onto the matching picture.","xp_reward":30,"vocab_config":{"items":[{"id":"pitch","english":"Pitch","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/wc/vocabulary/pitch.m4a.mp4","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/vocab/word-st5-pitch.png","translation":"Campo"},{"id":"penalty-area","english":"Penalty area","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/wc/vocabulary/pitch/penalty-area.m4a.mp4","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/vocab/penalty-area.png","translation":"Grande área"},{"id":"halfway-line","english":"Halfway line","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/wc/vocabulary/pitch/halfway-line.m4a.mp4","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/vocab/halfway-line.png","translation":"Linha do meio-campo"},{"id":"corner","english":"Corner","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/wc/vocabulary/pitch/corner.m4a.mp4","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/vocab/corner.png","translation":"Escanteio"}],"display_mode":"image"}},{"id":"step-5","type":"interactive_pitch_formation","title":"Tap the parts of the pitch","xp_reward":25,"formation_config":{"click_areas":[{"x":"25%","y":"50%","id":"halfway-line-area","label":"Halfway Line","label_pt":"Linha do meio-campo","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/wc/vocabulary/pitch/halfway-line.m4a.mp4","description":"","description_pt":""},{"x":"9%","y":"6%","id":"corner-area","label":"Corner","label_pt":"Escanteio","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/wc/vocabulary/pitch/corner.m4a.mp4","description":"","description_pt":""},{"x":"35%","y":"13%","id":"penalty-area","label":"Penalty Area","label_pt":"Grande área","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/wc/vocabulary/pitch/penalty-area.m4a.mp4","description":"","description_pt":""},{"x":"50%","y":"13%","id":"penalty-spot-area","label":"Penalty Spot","label_pt":"Marca do pênalti","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/wc/vocabulary/pitch/penalty-spot.m4a.mp4","description":"","description_pt":""},{"x":"8%","y":"30%","id":"sideline-area","label":"Sideline","label_pt":"Linha lateral","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/wc/vocabulary/pitch/sideline.m4a.mp4","description":"","description_pt":""},{"x":"50%","y":"5%","id":"goal-line-area","label":"Goal Line","label_pt":"Linha de gol","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/wc/vocabulary/pitch/goal-line.m4a.mp4","description":"","description_pt":""}],"formation_name":"","position_slots":[]},"replay_onboarding":true},{"id":"step-6","type":"vocabulary","title":"The lines and the spot","content":"Three more parts of the pitch — the ones that decide games.","vocabulary":[{"english":"penalty spot","example":"Messi placed the ball on the penalty spot.","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/wc/vocabulary/pitch/penalty-spot.m4a.mp4","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/vocab/penalty-spot.png","usage_tip":"The white spot 11 metres from goal — where penalties are taken.","translation":"marca do pênalti","pronunciation":"/ˈpɛnəlti spɒt/"},{"english":"sideline","example":"The winger stayed close to the sideline.","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/wc/vocabulary/pitch/sideline.m4a.mp4","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/vocab/side-line.png","usage_tip":"The long line on each side of the pitch. Ball out here = throw-in.","translation":"linha lateral","pronunciation":"/ˈsaɪdlaɪn/"},{"english":"goal line","example":"The ball crossed the goal line for a corner.","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/wc/vocabulary/pitch/goal-line.m4a.mp4","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/vocab/goal-line.png","usage_tip":"The line at each end of the pitch, between the corner flags.","translation":"linha de gol","pronunciation":"/ɡəʊl laɪn/"}]},{"id":"step-7","type":"drag_drop_vocab","title":"Match the lines and the spot","content":"Drag each English word onto the matching picture.","xp_reward":30,"vocab_config":{"items":[{"id":"penalty-spot","english":"Penalty spot","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/wc/vocabulary/pitch/penalty-spot.m4a.mp4","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/vocab/penalty-spot.png","translation":"Marca do pênalti"},{"id":"sideline","english":"Sideline","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/wc/vocabulary/pitch/sideline.m4a.mp4","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/vocab/side-line.png","translation":"Linha lateral"},{"id":"goal-line","english":"Goal line","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/wc/vocabulary/pitch/goal-line.m4a.mp4","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/vocab/goal-line.png","translation":"Linha de gol"}],"display_mode":"image"}},{"id":"step-8","type":"ai_gap_fill","title":"Penalty!","content":"Fill in the gap.","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/vocab/ball-on-penalty-spot.png","sentences":[{"id":"gap-1","text":"Saka places the ball on the penalty ___.","context":"Where penalty kicks are taken from","options":["spot","area","corner","line"],"hint_context":"A small white mark on the pitch.","correct_answers":["spot"]}],"xp_reward":20},{"id":"step-9","type":"ai_speech_practice","title":"Practice your pronunciation","prompt":"","context":"Parts of the pitch","xp_reward":20,"expectedText":"Pitch. Penalty area. Penalty spot. Halfway line. Corner. Sideline. Goal line.","instructions":{"en":"","pt":""}},{"id":"step-10","type":"memory_match","title":"Parts of the Pitch","xp_reward":60,"vocabulary":[{"en":"Pitch","id":1,"pt":"Campo","enImage":"","ptImage":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/vocab/word-st5-pitch.png"},{"en":"Penalty area","id":2,"pt":"Grande área","enImage":"","ptImage":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/vocab/penalty-area.png"},{"en":"Penalty spot","id":3,"pt":"Marca do pênalti","enImage":"","ptImage":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/vocab/penalty-spot.png"},{"en":"Halfway line","id":4,"pt":"Linha do meio-campo","enImage":"","ptImage":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/vocab/halfway-line.png"},{"en":"Corner","id":5,"pt":"Escanteio","enImage":"","ptImage":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/vocab/corner.png"},{"en":"Sideline","id":6,"pt":"Linha lateral","enImage":"","ptImage":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/vocab/side-line.png"},{"en":"Goal line","id":7,"pt":"Linha de gol","enImage":"","ptImage":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/vocab/goal-line.png"}],"display_mode":"image"},{"id":"step-11","type":"completion","title":"Ground Reader","content":"You know every important part of a football pitch — from the halfway line to the penalty spot. Every match commentary you''ll ever hear is built on these seven words. Next session: the eleven players who move around them.","xp_reward":120,"achievements":["✅ Seven parts of the pitch learned","✅ Interactive pitch identification passed","✅ Pronunciation practised"],"badge_unlocked":"Ground Reader","next_lesson_preview":"Next: Session 1.2 — The Team.","translation_available":true}],"session":1,"difficulty":"A1","skill_area":"tactics"}', null, null, null, true, 1, '2026-08-07 22:42:02.397347+00', '2026-08-07 22:42:02.397347+00', null, null, null, null, 1, 1, null, null, false, 'players', true, 'propath_26_27', ARRAY['tactics']), ('95e91bd7-68da-4a44-9bb6-59a80532f56a', '2. The Team', null, 101, 'Beginner', 100, '{"type":"multi_step","unit":1,"steps":[{"id":"step-1","type":"scenario","title":"2. The Team","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/vocab/striker.png"},{"id":"step-2","type":"interactive_pitch_formation","title":"Player positions: 4-3-3","xp_reward":20,"formation_config":{"mode":"presentation","formation_name":"4-3-3","position_slots":[{"x":"50%","y":"92%","id":"GK","label":"Goalkeeper","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/wc/vocabulary/positions/goalkeeper.m4a.mp4"},{"x":"15%","y":"75%","id":"LB","label":"Left Back","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/wc/vocabulary/positions/left-back.m4a.mp4"},{"x":"37%","y":"78%","id":"CB1","label":"Centre Back","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/wc/vocabulary/positions/centre-back.m4a.mp4"},{"x":"63%","y":"78%","id":"CB2","label":"Centre Back","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/wc/vocabulary/positions/centre-back.m4a.mp4"},{"x":"85%","y":"75%","id":"RB","label":"Right Back","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/wc/vocabulary/positions/right-back.m4a.mp4"},{"x":"30%","y":"55%","id":"CM1","label":"Central Midfielder","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/wc/vocabulary/positions/central-midfielder.m4a.mp4"},{"x":"50%","y":"50%","id":"CM2","label":"Central Midfielder","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/wc/vocabulary/positions/central-midfielder.m4a.mp4"},{"x":"70%","y":"55%","id":"CM3","label":"Central Midfielder","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/wc/vocabulary/positions/central-midfielder.m4a.mp4"},{"x":"18%","y":"28%","id":"LW","label":"Left Winger","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/wc/vocabulary/positions/left-winger.m4a.mp4"},{"x":"50%","y":"18%","id":"ST","label":"Striker","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/wc/vocabulary/positions/striker.m4a.mp4"},{"x":"82%","y":"28%","id":"RW","label":"Right Winger","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/wc/vocabulary/positions/right-winger.m4a.mp4"}]}},{"id":"step-3","type":"vocabulary","title":"The back four","content":"The goalkeeper and the three defensive positions in front of them. The wall that protects the goal.","vocabulary":[{"english":"goalkeeper","example":"The goalkeeper made a brilliant save with one hand.","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/wc/vocabulary/positions/goalkeeper.m4a.mp4","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/vocab/goalkeeper-one-hand-save.png","usage_tip":"Number 1. Wears a different colour shirt. The only player allowed to use hands — inside the penalty area only.","translation":"goleiro","pronunciation":"/ˈɡəʊlkiːpə/"},{"english":"centre-back","example":"The centre-back headed the ball clear.","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/wc/vocabulary/positions/centre-back.m4a.mp4","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/positions/centre-back.png","usage_tip":"In the middle of defence, usually two of them. Job: mark the striker, win headers, don''t get pulled out.","translation":"zagueiro central","pronunciation":"/ˈsentə bæk/"},{"english":"left-back","example":"The left-back overlapped down the wing.","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/wc/vocabulary/positions/left-back.m4a.mp4","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/positions/left-back.png","usage_tip":"The defender on the left side of the back four. Defends the left wing, attacks down it too.","translation":"lateral esquerdo","pronunciation":"/left bæk/"},{"english":"right-back","example":"The right-back put in a perfect cross.","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/wc/vocabulary/positions/right-back.m4a.mp4","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/positions/right-back.png","usage_tip":"The defender on the right side. Same job as the left-back, opposite side.","translation":"lateral direito","pronunciation":"/raɪt bæk/"}]},{"id":"step-4","type":"drag_drop_vocab","title":"Match the back four","content":"Drag each position name onto the matching picture.","xp_reward":30,"vocab_config":{"items":[{"id":"gk-back","english":"Goalkeeper","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/wc/vocabulary/positions/goalkeeper.m4a.mp4","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/vocab/goalkeeper-one-hand-save.png","translation":"Goleiro"},{"id":"cb-back","english":"Centre-back","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/wc/vocabulary/positions/centre-back.m4a.mp4","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/positions/centre-back.png","translation":"Zagueiro central"},{"id":"lb-back","english":"Left-back","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/wc/vocabulary/positions/left-back.m4a.mp4","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/positions/left-back.png","translation":"Lateral esquerdo"},{"id":"rb-back","english":"Right-back","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/wc/vocabulary/positions/right-back.m4a.mp4","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/positions/right-back.png","translation":"Lateral direito"}],"display_mode":"image"}},{"id":"step-5","type":"vocabulary","title":"Midfield and attack","content":"The four positions where matches are usually won.","vocabulary":[{"english":"central midfielder","example":"The central midfielder controls the tempo of the game.","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/wc/vocabulary/positions/central-midfielder.m4a.mp4","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/positions/central-midfielder.png","usage_tip":"The engine of the team. Links defence to attack. Runs 12+ km a match in modern football.","translation":"meio-campista","pronunciation":"/ˈsentrəl ˈmɪdfiːldə/"},{"english":"left winger","example":"The left winger cut inside and shot on his right foot.","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/wc/vocabulary/positions/left-winger.m4a.mp4","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/positions/left-winger.png","usage_tip":"Wide attacker on the left. Pace, dribbling, crossing. Often cuts inside to shoot.","translation":"ponta esquerda","pronunciation":"/left ˈwɪŋə/"},{"english":"right winger","example":"The right winger sprinted past the full-back and crossed it.","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/wc/vocabulary/positions/right-winger.m4a.mp4","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/positions/right-winger.png","usage_tip":"Wide attacker on the right. Beats defenders one-on-one, delivers dangerous crosses.","translation":"ponta direita","pronunciation":"/raɪt ˈwɪŋə/"},{"english":"striker","example":"The striker scored his fifth goal of the tournament.","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/wc/vocabulary/positions/striker.m4a.mp4","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/vocab/striker.png","usage_tip":"The number 9. Job: put the ball in the net. Anywhere. Anyhow.","translation":"atacante / centroavante","pronunciation":"/ˈstraɪkə/"}]},{"id":"step-6","type":"drag_drop_vocab","title":"Match midfield and attack","content":"Drag each position name onto the matching picture.","xp_reward":30,"vocab_config":{"items":[{"id":"cm-mid","english":"Central midfielder","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/wc/vocabulary/positions/central-midfielder.m4a.mp4","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/positions/central-midfielder.png","translation":"Meio-campista"},{"id":"lw-mid","english":"Left winger","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/wc/vocabulary/positions/left-winger.m4a.mp4","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/positions/left-winger.png","translation":"Ponta esquerda"},{"id":"rw-mid","english":"Right winger","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/wc/vocabulary/positions/right-winger.m4a.mp4","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/positions/right-winger.png","translation":"Ponta direita"},{"id":"st-mid","english":"Striker","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/wc/vocabulary/positions/striker.m4a.mp4","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/vocab/striker.png","translation":"Atacante"}],"display_mode":"image"}},{"id":"step-7","type":"drag_drop_formation","title":"Build a 4-3-3","content":"Drag each player card into the right position on the pitch.","xp_reward":55,"formation_config":{"validation":"match_position_to_slot_accepts","pitch_image":"","player_cards":[{"id":"p1","name":"Goalkeeper","position":"goalkeeper","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/wc/formations/cards/1g.png"},{"id":"p2","name":"Left Back","position":"left-back","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/wc/formations/cards/3.png"},{"id":"p3","name":"Centre Back","position":"center-back","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/wc/formations/cards/4.png"},{"id":"p4","name":"Centre Back","position":"center-back","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/wc/formations/cards/5.png"},{"id":"p5","name":"Right Back","position":"right-back","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/wc/formations/cards/2.png"},{"id":"p6","name":"Central Midfielder","position":"central-midfielder","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/wc/formations/cards/6.png"},{"id":"p7","name":"Central Midfielder","position":"central-midfielder","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/wc/formations/cards/8.png"},{"id":"p8","name":"Central Midfielder","position":"central-midfielder","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/wc/formations/cards/10.png"},{"id":"p9","name":"Left Winger","position":"left-winger","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/wc/formations/cards/11.png"},{"id":"p10","name":"Striker","position":"striker","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/wc/formations/cards/9.png"},{"id":"p11","name":"Right Winger","position":"right-winger","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/wc/formations/cards/7.png"}],"formation_name":"4-3-3","position_slots":[{"x":"50%","y":"92%","id":"GK","label":"Goalkeeper","accepts":["goalkeeper"]},{"x":"15%","y":"72%","id":"LB","label":"Left Back","accepts":["left-back","full-back"]},{"x":"38%","y":"76%","id":"CB1","label":"Centre Back","accepts":["center-back"]},{"x":"62%","y":"76%","id":"CB2","label":"Centre Back","accepts":["center-back"]},{"x":"85%","y":"72%","id":"RB","label":"Right Back","accepts":["right-back","full-back"]},{"x":"30%","y":"55%","id":"CM1","label":"Central Midfielder","accepts":["central-midfielder"]},{"x":"50%","y":"50%","id":"CM2","label":"Central Midfielder","accepts":["central-midfielder"]},{"x":"70%","y":"55%","id":"CM3","label":"Central Midfielder","accepts":["central-midfielder"]},{"x":"20%","y":"25%","id":"LW","label":"Left Winger","accepts":["left-winger","winger"]},{"x":"50%","y":"18%","id":"ST","label":"Striker","accepts":["striker"]},{"x":"80%","y":"25%","id":"RW","label":"Right Winger","accepts":["right-winger","winger"]}]}},{"id":"step-8","type":"vocabulary","title":"The three main formations","content":"Every coach in the world uses one of these three shapes as their base. Learn them — you''ll hear them in every dressing room.","vocabulary":[{"english":"4-3-3","example":"Pep Guardiola loves the 4-3-3.","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/wc/vocabulary/tactics/four-three-three.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/vocab/433.png","usage_tip":"Four defenders, three midfielders, three forwards. Balanced, attacking, most common today.","translation":"4-3-3","pronunciation":"/fɔː θriː θriː/"},{"english":"4-4-2","example":"England''s classic 4-4-2 brought them success in the 90s.","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/wc/vocabulary/tactics/four-four-two.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/vocab/442.png","usage_tip":"Four defenders, four midfielders, two strikers. Solid and traditional.","translation":"4-4-2","pronunciation":"/fɔː fɔː tuː/"},{"english":"4-2-3-1","example":"Brazil''s 4-2-3-1 gives them creativity and balance.","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/wc/vocabulary/tactics/four-two-three-one.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/vocab/4231.png","usage_tip":"Two defensive midfielders, three attacking midfielders, one striker. Modern coach''s favourite.","translation":"4-2-3-1","pronunciation":"/fɔː tuː θriː wʌn/"}]},{"id":"step-9","type":"drag_drop_vocab","title":"Match the formation","content":"Drag each formation name onto its shape.","xp_reward":25,"vocab_config":{"items":[{"id":"433f","english":"4-3-3","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/wc/vocabulary/tactics/four-three-three.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/vocab/433.png","translation":"4-3-3"},{"id":"442f","english":"4-4-2","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/wc/vocabulary/tactics/four-four-two.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/vocab/442.png","translation":"4-4-2"},{"id":"4231f","english":"4-2-3-1","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/wc/vocabulary/tactics/four-two-three-one.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/vocab/4231.png","translation":"4-2-3-1"}],"display_mode":"image"}},{"id":"step-10","type":"interactive_game_formation","title":"Pass the ball: coach''s commands","xp_reward":60,"formation_config":{"timing":{"enabled":true},"commands":[{"id":"cmd-1","text":"Pass to the left back.","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/wc/vocabulary/pass/pass-to-the-left-back.m4a.mp4","translation":"Passe para o lateral esquerdo.","target_slot_id":"LB","success_message":""},{"id":"cmd-2","text":"Pass to the right back.","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/wc/vocabulary/pass/pass-to-the-right-back.m4a.mp4","translation":"Passe para o lateral direito.","target_slot_id":"RB","success_message":""},{"id":"cmd-3","text":"Pass to the central midfielder.","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/wc/vocabulary/pass/pass-to-the-central-midfielder.m4a.mp4","translation":"Passe para o meio-campista.","success_message":"","target_slot_ids":["CM1","CM2","CM3"]},{"id":"cmd-4","text":"Pass to the centre back.","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/wc/vocabulary/pass/pass-to-the-centre-back.m4a.mp4","translation":"Passe para o zagueiro.","success_message":"","target_slot_ids":["CB1","CB2"]},{"id":"cmd-5","text":"Pass to the left winger.","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/wc/vocabulary/pass/pass-to-the-left-winger.m4a.mp4","translation":"Passe para o ponta esquerda.","target_slot_id":"LW","success_message":""},{"id":"cmd-6","text":"Pass to the right winger.","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/wc/vocabulary/pass/pass-to-the-right-winger.m4a.mp4","translation":"Passe para o ponta direita.","target_slot_id":"RW","success_message":""},{"id":"cmd-7","text":"Cross to the striker.","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/wc/vocabulary/pass/cross-to-the-striker.m4a.mp4","translation":"Cruze para o atacante.","target_slot_id":"ST","success_message":"Super cross!"},{"id":"cmd-8","text":"Play a long ball to the right winger.","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/wc/vocabulary/pass/play-a-long-ball-to-the-rightwinger.m4a.mp4","translation":"Lançamento para o ponta direita.","target_slot_id":"RW","success_message":""},{"id":"cmd-9","text":"Kick to the goal!","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/wc/vocabulary/pass/kick-to-the-goal.m4a.mp4","translation":"Chuta pro gol!","target_slot_id":"GOAL","success_message":"Great goal!"}],"formation_name":"4-3-3","position_slots":[{"x":"50%","y":"92%","id":"GK","label":"Goalkeeper"},{"x":"15%","y":"75%","id":"LB","label":"Left Back"},{"x":"37%","y":"78%","id":"CB1","label":"Centre Back"},{"x":"63%","y":"78%","id":"CB2","label":"Centre Back"},{"x":"85%","y":"75%","id":"RB","label":"Right Back"},{"x":"30%","y":"55%","id":"CM1","label":"Central Mid"},{"x":"50%","y":"50%","id":"CM2","label":"Central Mid"},{"x":"70%","y":"55%","id":"CM3","label":"Central Mid"},{"x":"18%","y":"28%","id":"LW","label":"Left Wing"},{"x":"50%","y":"18%","id":"ST","label":"Striker"},{"x":"82%","y":"28%","id":"RW","label":"Right Wing"}]}},{"id":"step-11","type":"ai_speech_practice","title":"Practice your pronunciation","prompt":"","context":"Positions and formations","xp_reward":20,"expectedText":"Goalkeeper. Centre-back. Left-back. Right-back. Central midfielder. Left winger. Right winger. Striker.","instructions":{"en":"","pt":""}},{"id":"step-12","type":"memory_match","title":"Team and shape review","xp_reward":60,"vocabulary":[{"en":"Goalkeeper","id":1,"pt":"Goleiro","enImage":"","ptImage":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/vocab/goalkeeper-one-hand-save.png"},{"en":"Centre-back","id":2,"pt":"Zagueiro central","enImage":"","ptImage":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/positions/centre-back.png"},{"en":"Left-back","id":3,"pt":"Lateral esquerdo","enImage":"","ptImage":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/positions/left-back.png"},{"en":"Right-back","id":4,"pt":"Lateral direito","enImage":"","ptImage":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/positions/right-back.png"},{"en":"Central midfielder","id":5,"pt":"Meio-campista","enImage":"","ptImage":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/positions/central-midfielder.png"},{"en":"Striker","id":6,"pt":"Atacante","enImage":"","ptImage":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/vocab/striker.png"},{"en":"4-3-3","id":7,"pt":"4-3-3","enImage":"","ptImage":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/vocab/433.png"},{"en":"4-4-2","id":8,"pt":"4-4-2","enImage":"","ptImage":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/vocab/442.png"}],"display_mode":"image"},{"id":"step-13","type":"completion","title":"Shape Reader","content":"You know every position on the pitch, you''ve built your first 4-3-3 by hand, and you''ve followed a coach''s commands in real time. The team''s shape is now yours to read. Next session: meeting the people who play in it.","xp_reward":140,"achievements":["✅ Eight positions learned","✅ Three main formations recognised","✅ First 4-3-3 built by hand","✅ Nine coach''s commands understood"],"badge_unlocked":"Shape Reader","next_lesson_preview":"Next: Session 1.3 — Meet Your Team.","translation_available":true}],"session":2,"difficulty":"A1","skill_area":"tactics"}', null, null, null, true, 2, '2026-08-08 01:49:15.112921+00', '2026-08-08 01:49:15.112921+00', null, null, null, null, 1, 2, '', null, false, 'players', true, 'propath_26_27', ARRAY['tactics']), ('a0fefd7d-31b3-4dc7-9d46-26a66f07eae6', '3. Meet Your Team', null, 101, 'Beginner', 100, '{"type":"multi_step","unit":1,"steps":[{"id":"step-1","type":"scenario","title":"3. Meet Your Team","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/scenarios/dressing-room.png"},{"id":"step-2","type":"vocabulary","title":"First greetings","content":"You walk into the dressing room. Twenty teammates you''ve never met. You have five seconds to make a first impression. These four phrases carry it.","vocabulary":[{"english":"Good morning!","example":"Good morning, coach!","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/greetings/good-morning.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/greetings/good-morning.png","usage_tip":"Used until about midday. The most common way to start a training day.","translation":"Bom dia!","pronunciation":"/ɡʊd ˈmɔːnɪŋ/"},{"english":"Hello!","example":"Hello — I''m Diego.","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/greetings/hello.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/greetings/hello.png","usage_tip":"Works at any time of day. Simple, universal, safe.","translation":"Olá!","pronunciation":"/həˈləʊ/"},{"english":"How are you?","example":"How are you, mate?","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/greetings/how-are-you.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/greetings/how-are-you.png","usage_tip":"Ask this after saying hello. Even if you don''t want a real answer — it''s the polite thing to do.","translation":"Como você está?","pronunciation":"/haʊ ɑː juː/"},{"english":"I''m fine, thanks. And you?","example":"I''m fine, thanks. And you?","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/greetings/im-fine-thanks.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/greetings/im-fine-thanks.png","usage_tip":"The safe answer, always. Adding ''And you?'' shows you''re interested — it goes a long way.","translation":"Estou bem, obrigado. E você?","pronunciation":"/aɪm faɪn θæŋks ənd juː/"}]},{"id":"step-3","type":"drag_drop_vocab","title":"Match the greeting","content":"Drag each greeting onto the matching picture.","xp_reward":30,"vocab_config":{"items":[{"id":"g-morning","english":"Good morning!","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/greetings/good-morning.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/greetings/good-morning.png","translation":"Bom dia!"},{"id":"g-hello","english":"Hello!","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/greetings/hello.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/greetings/hello.png","translation":"Olá!"},{"id":"g-how","english":"How are you?","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/greetings/how-are-you.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/greetings/how-are-you.png","translation":"Como você está?"},{"id":"g-fine","english":"I''m fine, thanks. And you?","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/greetings/im-fine-thanks.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/greetings/im-fine-thanks.png","translation":"Estou bem, obrigado. E você?"}],"display_mode":"image"}},{"id":"step-4","type":"vocabulary","title":"Introducing yourself","content":"Now they know your face. Four short sentences and they know who you are.","vocabulary":[{"english":"I''m [name].","example":"I''m Diego.","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/introductions/im-name.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/introductions/im-name.png","usage_tip":"Short, direct, confident. Not ''my name is''. Real English footballers say ''I''m Marcus'', not ''my name is Marcus''.","translation":"Sou o [nome].","pronunciation":"/aɪm/"},{"english":"I''m from Brazil.","example":"I''m from Brazil — from São Paulo.","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/introductions/im-from-brazil.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/introductions/im-from-brazil.png","usage_tip":"Swap ''Brazil'' for wherever you''re from. Adding your city is optional — but shows warmth.","translation":"Sou do Brasil.","pronunciation":"/aɪm frɒm brəˈzɪl/"},{"english":"I play as a [position].","example":"I play as a right winger.","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/introductions/i-play-as.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/introductions/i-play-as.png","usage_tip":"The most important sentence you''ll say all day. Insert your position clearly. Coaches remember it.","translation":"Jogo como [posição].","pronunciation":"/aɪ pleɪ əz/"},{"english":"Nice to meet you.","example":"Nice to meet you, mate.","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/introductions/nice-to-meet-you.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/introductions/nice-to-meet-you.png","usage_tip":"The end of every first introduction. A short handshake with it. Then the football starts.","translation":"Prazer em conhecê-lo.","pronunciation":"/naɪs tə miːt juː/"}]},{"id":"step-5","type":"drag_drop_vocab","title":"Match the introduction","content":"Drag each phrase onto the matching picture.","xp_reward":30,"vocab_config":{"items":[{"id":"i-name","english":"I''m [name].","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/introductions/im-name.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/introductions/im-name.png","translation":"Sou o [nome]."},{"id":"i-from","english":"I''m from Brazil.","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/introductions/im-from-brazil.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/introductions/im-from-brazil.png","translation":"Sou do Brasil."},{"id":"i-play","english":"I play as a [position].","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/introductions/i-play-as.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/introductions/i-play-as.png","translation":"Jogo como [posição]."},{"id":"i-nice","english":"Nice to meet you.","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/introductions/nice-to-meet-you.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/introductions/nice-to-meet-you.png","translation":"Prazer em conhecê-lo."}],"display_mode":"image"}},{"id":"step-6","type":"ai_gap_fill","title":"Complete the dressing room dialogue","content":"Fill in the gap.","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/scenarios/dressing-room.png","sentences":[{"id":"gap-1","text":"''Good morning!'' — ''Good morning! I''m Diego. ___ from Brazil.''","context":"Introducing where you''re from","options":["I''m","I","My","Me"],"hint_context":"The short form of ''I am''.","correct_answers":["I''m"]},{"id":"gap-2","text":"''I play as a right winger. Nice to ___ you.''","context":"The polite way to end a first introduction","options":["meet","see","know","greet"],"hint_context":"The standard English phrase.","correct_answers":["meet"]}],"xp_reward":25},{"id":"step-7","type":"ai_speech_practice","title":"Practise the greetings","prompt":"","context":"Meeting the team","xp_reward":20,"expectedText":"Good morning! Hello. How are you? I''m fine, thanks. And you?","instructions":{"en":"Warm voice, eye contact, clear vowels. Nothing complicated — just confident.","pt":"Voz calorosa, olho no olho, vogais claras. Nada complicado — só confiante."}},{"id":"step-8","type":"ai_speech_practice","title":"Introduce yourself","prompt":"","context":"Your first introduction to a new team","xp_reward":30,"expectedText":"Hello, I''m Diego. I''m from Brazil. I play as a right winger. Nice to meet you.","instructions":{"en":"Say your real name and your real position. Rehearse it — you''ll use this sentence dozens of times in your first week.","pt":"Diga seu nome verdadeiro e sua posição verdadeira. Ensaie — você vai usar essa frase dezenas de vezes na primeira semana."}},{"id":"step-9","type":"memory_match","title":"Greetings and introductions review","xp_reward":60,"vocabulary":[{"en":"Good morning!","id":1,"pt":"Bom dia!","enImage":"","ptImage":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/greetings/good-morning.png"},{"en":"Hello!","id":2,"pt":"Olá!","enImage":"","ptImage":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/greetings/hello.png"},{"en":"How are you?","id":3,"pt":"Como você está?","enImage":"","ptImage":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/greetings/how-are-you.png"},{"en":"I''m fine, thanks.","id":4,"pt":"Estou bem, obrigado.","enImage":"","ptImage":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/greetings/im-fine-thanks.png"},{"en":"I''m from Brazil.","id":5,"pt":"Sou do Brasil.","enImage":"","ptImage":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/introductions/im-from-brazil.png"},{"en":"I play as a right winger.","id":6,"pt":"Jogo como ponta direita.","enImage":"","ptImage":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/introductions/i-play-as.png"},{"en":"Nice to meet you.","id":7,"pt":"Prazer em conhecê-lo.","enImage":"","ptImage":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/introductions/nice-to-meet-you.png"}],"display_mode":"image"},{"id":"step-10","type":"completion","title":"First Voice","content":"You can walk into any dressing room in the world, say hello, introduce yourself, and tell them what position you play. That''s the first impression a coach and a squad ever get of you. You just built it in English.","xp_reward":120,"achievements":["✅ Four greetings learned","✅ Four introduction phrases mastered","✅ First dressing-room dialogue completed","✅ Full self-introduction spoken"],"badge_unlocked":"First Voice","next_lesson_preview":"Next: Session 1.4 — The Kit.","translation_available":true}],"session":3,"difficulty":"A1","skill_area":"pitch-talk"}', null, null, null, true, 3, '2026-08-13 20:37:23.297342+00', '2026-08-13 20:37:23.297342+00', null, null, null, null, 1, 3, null, null, false, 'players', false, 'propath_26_27', ARRAY['pitch_talk']), ('f8cd2814-05ce-4a26-a23f-875bcd571543', '4. The Kit', null, 101, 'Beginner', 100, '{"type":"multi_step","unit":1,"steps":[{"id":"step-1","type":"scenario","title":"4. The Kit","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/scenarios/changing-room.png"},{"id":"step-2","type":"vocabulary","title":"Your kit","content":"Everything you need on your body before you step on the pitch. Five items — miss one and you can''t play.","vocabulary":[{"english":"boots","example":"Put on your boots.","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/kit/boots.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/kit/boots.png","usage_tip":"British/international. Americans say ''cleats''. Always plural — ''my boots'', never ''my boot''.","translation":"chuteiras","pronunciation":"/buːts/"},{"english":"shin pads","example":"Don''t forget your shin pads.","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/kit/shin-pads.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/kit/shin-pads.png","usage_tip":"Compulsory in every professional match. The referee will check them before kick-off.","translation":"caneleiras","pronunciation":"/ʃɪn pædz/"},{"english":"shirt","example":"Wear your shirt with pride.","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/kit/shirt.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/kit/shirt.png","usage_tip":"Also called ''jersey''. Both are fine. ''Shirt'' is more common in British football.","translation":"camisa","pronunciation":"/ʃɜːt/"},{"english":"shorts","example":"Your shorts are in the locker.","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/kit/shorts.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/kit/shorts.png","usage_tip":"Always plural — ''my shorts'', never ''my short''.","translation":"calção","pronunciation":"/ʃɔːts/"},{"english":"socks","example":"Pull your socks up over your shin pads.","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/kit/socks.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/kit/socks.png","usage_tip":"The long football socks that go over the shin pads. Always plural.","translation":"meias","pronunciation":"/sɒks/"}]},{"id":"step-3","type":"drag_drop_vocab","title":"Match your kit","content":"Drag each item onto the matching picture.","xp_reward":30,"vocab_config":{"items":[{"id":"k-boots","english":"Boots","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/kit/boots.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/kit/boots.png","translation":"Chuteiras"},{"id":"k-shin","english":"Shin pads","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/kit/shin-pads.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/kit/shin-pads.png","translation":"Caneleiras"},{"id":"k-shirt","english":"Shirt","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/kit/shirt.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/kit/shirt.png","translation":"Camisa"},{"id":"k-shorts","english":"Shorts","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/kit/shorts.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/kit/shorts.png","translation":"Calção"},{"id":"k-socks","english":"Socks","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/kit/socks.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/kit/socks.png","translation":"Meias"}],"display_mode":"image"}},{"id":"step-4","type":"vocabulary","title":"Extras and armband","content":"Three more items — one for the keeper, one for the leader, one for everyone.","vocabulary":[{"english":"gloves","example":"The goalkeeper puts on his gloves.","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/kit/gloves.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/kit/gloves.png","usage_tip":"Only the goalkeeper. Always plural. Never say ''a glove'' — say ''a pair of gloves''.","translation":"luvas","pronunciation":"/ɡlʌvz/"},{"english":"captain''s armband","example":"The captain wears the armband.","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/kit/captains-armband.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/kit/captains-armband.png","usage_tip":"The coloured band on the captain''s upper arm. Shows who leads the team on the pitch.","translation":"braçadeira de capitão","pronunciation":"/ˈkæptɪnz ˈɑːmbænd/"},{"english":"water bottle","example":"Always bring your water bottle.","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/kit/water-bottle.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/kit/water-bottle.png","usage_tip":"Never share bottles at a professional level. Your name goes on yours.","translation":"garrafa de água","pronunciation":"/ˈwɔːtə ˈbɒtəl/"}]},{"id":"step-5","type":"ai_speech_practice","title":"Practise the kit vocabulary","prompt":"","context":"Match-day kit","xp_reward":20,"expectedText":"Boots. Shin pads. Shirt. Shorts. Socks. Gloves. Captain''s armband. Water bottle.","instructions":{"en":"","pt":""}},{"id":"step-6","type":"vocabulary","title":"Warm-up actions","content":"Before you touch the ball, you touch these four actions. The warm-up is where the trial coaches watch how professional you are.","vocabulary":[{"english":"stretch","example":"Stretch your hamstrings.","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/warmup/stretch.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/warmup/stretch.png","usage_tip":"Prepare your muscles slowly and deliberately. Don''t rush a stretch.","translation":"alongar","pronunciation":"/stretʃ/"},{"english":"jog","example":"Jog around the pitch to warm up.","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/warmup/jog.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/warmup/jog.png","usage_tip":"Run slowly and easily. Not a race — you''re waking up the body.","translation":"trotar","pronunciation":"/dʒɒɡ/"},{"english":"sprint","example":"Sprint to the halfway line and back.","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/warmup/sprint.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/warmup/sprint.png","usage_tip":"The opposite of jogging. Maximum speed, short distance. Coaches see who has real pace here.","translation":"sprintar / correr em velocidade","pronunciation":"/sprɪnt/"},{"english":"jump","example":"Jump and reach for the crossbar.","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/warmup/jump.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/warmup/jump.png","usage_tip":"Explosive vertical push. Used in warm-ups to prepare for headers and aerial duels.","translation":"pular","pronunciation":"/dʒʌmp/"}]},{"id":"step-7","type":"drag_drop_vocab","title":"Match the warm-up","content":"Drag each action onto the matching picture.","xp_reward":30,"vocab_config":{"items":[{"id":"w-stretch","english":"Stretch","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/warmup/stretch.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/warmup/stretch.png","translation":"Alongar"},{"id":"w-jog","english":"Jog","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/warmup/jog.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/warmup/jog.png","translation":"Trotar"},{"id":"w-sprint","english":"Sprint","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/warmup/sprint.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/warmup/sprint.png","translation":"Sprintar"},{"id":"w-jump","english":"Jump","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/warmup/jump.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/warmup/jump.png","translation":"Pular"}],"display_mode":"image"}},{"id":"step-8","type":"ai_gap_fill","title":"Getting ready","content":"Fill in the gap.","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/scenarios/changing-room.png","sentences":[{"id":"gap-1","text":"''Don''t forget your ___ pads — the ref will check.''","context":"The compulsory protective gear","options":["shin","knee","elbow","leg"],"hint_context":"Protect the lower leg.","correct_answers":["shin"]},{"id":"gap-2","text":"''Warm up first — ___ your hamstrings before you sprint.''","context":"What you do to your muscles first","options":["stretch","kick","run","shoot"],"hint_context":"A slow, deliberate movement.","correct_answers":["stretch"]}],"xp_reward":25},{"id":"step-9","type":"memory_match","title":"Kit and warm-up review","xp_reward":60,"vocabulary":[{"en":"Boots","id":1,"pt":"Chuteiras","enImage":"","ptImage":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/kit/boots.png"},{"en":"Shin pads","id":2,"pt":"Caneleiras","enImage":"","ptImage":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/kit/shin-pads.png"},{"en":"Shirt","id":3,"pt":"Camisa","enImage":"","ptImage":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/kit/shirt.png"},{"en":"Gloves","id":4,"pt":"Luvas","enImage":"","ptImage":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/kit/gloves.png"},{"en":"Captain''s armband","id":5,"pt":"Braçadeira de capitão","enImage":"","ptImage":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/kit/captains-armband.png"},{"en":"Stretch","id":6,"pt":"Alongar","enImage":"","ptImage":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/warmup/stretch.png"},{"en":"Sprint","id":7,"pt":"Sprintar","enImage":"","ptImage":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/warmup/sprint.png"},{"en":"Jump","id":8,"pt":"Pular","enImage":"","ptImage":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/warmup/jump.png"}],"display_mode":"image"},{"id":"step-10","type":"completion","title":"Kit Ready","content":"You can walk into any changing room in the world and know what to put on, in what order, and what to do next. The warm-up is where trial coaches decide who''s serious — you have the vocabulary to be one of the ones they notice.","xp_reward":120,"achievements":["✅ Eight kit items learned","✅ Four warm-up actions mastered","✅ First changing-room dialogue completed"],"badge_unlocked":"Kit Ready","next_lesson_preview":"Next: Session 1.5 — The Coach''s Commands.","translation_available":true}],"session":4,"difficulty":"A1","skill_area":"fitness"}', null, null, null, true, 4, '2026-08-13 20:39:10.183101+00', '2026-08-13 20:39:10.183101+00', null, null, null, null, 1, 4, null, null, false, 'players', false, 'propath_26_27', ARRAY['fitness']), ('2a97287b-4357-42b0-815f-39903c142919', '5. Coach''s Commands', null, 101, null, 100, '{"type":"multi_step","unit":1,"steps":[{"id":"step-1","type":"scenario","title":"5. The Coach''s Commands","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/scenarios/coach-clipboard.png"},{"id":"step-2","type":"vocabulary","title":"What to do with the ball","content":"The four commands you''ll hear ten times a training session. Short, sharp, non-negotiable. Learn them so you don''t have to think.","vocabulary":[{"english":"pass","example":"Pass the ball to your teammate.","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/wc/vocabulary/kick.m4a.mp4","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/commands/pass.png","usage_tip":"The most common command you''ll hear. React fast — don''t hold the ball too long.","translation":"passar","pronunciation":"/pɑːs/"},{"english":"kick","example":"Kick the ball forward.","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/wc/vocabulary/kick.m4a.mp4","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/vocab/word-st5-kick.png","usage_tip":"General term for hitting the ball with the foot. Coaches use it when they want you to just clear or move it.","translation":"chutar","pronunciation":"/kɪk/"},{"english":"shoot","example":"Shoot at the goal!","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/commands/shoot.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/commands/shoot.png","usage_tip":"Kick towards the goal aiming to score. When a coach shouts ''shoot!'' — don''t hesitate. Shoot.","translation":"chutar ao gol","pronunciation":"/ʃuːt/"},{"english":"cross","example":"Cross the ball to the striker.","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/commands/cross.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/commands/cross.png","usage_tip":"Send the ball from the wing into the penalty area. The winger''s most important command.","translation":"cruzar","pronunciation":"/krɒs/"}]},{"id":"step-3","type":"drag_drop_vocab","title":"Match the ball command","content":"Drag each command onto the matching picture.","xp_reward":30,"vocab_config":{"items":[{"id":"c-pass","english":"Pass","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/wc/vocabulary/kick.m4a.mp4","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/commands/pass.png","translation":"Passar"},{"id":"c-kick","english":"Kick","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/wc/vocabulary/kick.m4a.mp4","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/vocab/word-st5-kick.png","translation":"Chutar"},{"id":"c-shoot","english":"Shoot","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/commands/shoot.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/commands/shoot.png","translation":"Chutar ao gol"},{"id":"c-cross","english":"Cross","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/commands/cross.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/commands/cross.png","translation":"Cruzar"}],"display_mode":"image"}},{"id":"step-4","type":"vocabulary","title":"How to move","content":"The four commands about your body''s movement — with or without the ball.","vocabulary":[{"english":"attack","example":"Attack down the right side.","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/wc/vocabulary/tactics/attack.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/vocab/attack.png","usage_tip":"Move forward towards the opponent''s goal. Also a noun: ''the attack down the wing''.","translation":"atacar","pronunciation":"/əˈtæk/"},{"english":"defend","example":"Defend the left side.","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/commands/defend.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/vocab/defence.png","usage_tip":"Stop the opponent scoring. Track back, mark your player, don''t switch off.","translation":"defender","pronunciation":"/dɪˈfend/"},{"english":"press","example":"Press their midfielder!","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/wc/vocabulary/tactics/press.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/vocab/press.png","usage_tip":"Put immediate pressure on an opponent with the ball. Close them down fast, force a mistake.","translation":"pressionar","pronunciation":"/pres/"},{"english":"run","example":"Run into the space.","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/commands/run.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/commands/run.png","usage_tip":"Move without the ball. Runs into space create chances — the coach notices when you make them.","translation":"correr","pronunciation":"/rʌn/"}]},{"id":"step-5","type":"drag_drop_vocab","title":"Match the movement command","content":"Drag each command onto the matching picture.","xp_reward":30,"vocab_config":{"items":[{"id":"m-attack","english":"Attack","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/wc/vocabulary/tactics/attack.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/vocab/attack.png","translation":"Atacar"},{"id":"m-defend","english":"Defend","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/commands/defend.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/vocab/defence.png","translation":"Defender"},{"id":"m-press","english":"Press","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/wc/vocabulary/tactics/press.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/vocab/press.png","translation":"Pressionar"},{"id":"m-run","english":"Run","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/commands/run.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/commands/run.png","translation":"Correr"}],"display_mode":"image"}},{"id":"step-6","type":"interactive_game_formation","title":"Follow the coach in real time","xp_reward":60,"formation_config":{"timing":{"enabled":true},"commands":[{"id":"cmd-c1","text":"Pass back to the goalkeeper.","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/commands/pass-back-to-goalkeeper.m4a","translation":"Passe de volta para o goleiro.","target_slot_id":"GK","success_message":""},{"id":"cmd-c2","text":"Pass to the central midfielder.","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/wc/vocabulary/pass/pass-to-the-central-midfielder.m4a.mp4","translation":"Passe para o meio-campista.","success_message":"","target_slot_ids":["CM1","CM2","CM3"]},{"id":"cmd-c3","text":"Play a long ball to the striker.","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/wc/vocabulary/pass/play-a-long-ball-to-the-striker.m4a.mp4","translation":"Lançamento para o atacante.","target_slot_id":"ST","success_message":""},{"id":"cmd-c4","text":"Cross to the striker.","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/wc/vocabulary/pass/cross-to-the-striker.m4a.mp4","translation":"Cruze para o atacante.","target_slot_id":"ST","success_message":"Super cross!"},{"id":"cmd-c5","text":"Pass to the left winger.","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/wc/vocabulary/pass/pass-to-the-left-winger.m4a.mp4","translation":"Passe para o ponta esquerda.","target_slot_id":"LW","success_message":""},{"id":"cmd-c6","text":"Pass to the right winger.","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/wc/vocabulary/pass/pass-to-the-right-winger.m4a.mp4","translation":"Passe para o ponta direita.","target_slot_id":"RW","success_message":""},{"id":"cmd-c7","text":"Kick to the goal!","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/wc/vocabulary/pass/kick-to-the-goal.m4a.mp4","translation":"Chuta pro gol!","target_slot_id":"GOAL","success_message":"Great goal!"}],"formation_name":"4-3-3","position_slots":[{"x":"50%","y":"92%","id":"GK","label":"Goalkeeper"},{"x":"15%","y":"75%","id":"LB","label":"Left Back"},{"x":"37%","y":"78%","id":"CB1","label":"Centre Back"},{"x":"63%","y":"78%","id":"CB2","label":"Centre Back"},{"x":"85%","y":"75%","id":"RB","label":"Right Back"},{"x":"30%","y":"55%","id":"CM1","label":"Central Mid"},{"x":"50%","y":"50%","id":"CM2","label":"Central Mid"},{"x":"70%","y":"55%","id":"CM3","label":"Central Mid"},{"x":"18%","y":"28%","id":"LW","label":"Left Wing"},{"x":"50%","y":"18%","id":"ST","label":"Striker"},{"x":"82%","y":"28%","id":"RW","label":"Right Wing"}]}},{"id":"step-7","type":"ai_speech_practice","title":"Practise the commands","prompt":"","context":"The coach''s key commands","xp_reward":20,"expectedText":"Pass. Kick. Shoot. Cross. Attack. Defend. Press. Run.","instructions":{"en":"Sharp, clear, loud enough for a teammate 30 metres away.","pt":"Nítido, claro, alto o suficiente para um companheiro a 30 metros."}},{"id":"step-8","type":"ai_gap_fill","title":"What did the coach say?","content":"Fill in the gap.","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/scenarios/coach-clipboard.png","sentences":[{"id":"gap-1","text":"''When we have the ball — ___ down the right!''","context":"Move forward with the ball","options":["attack","defend","wait","stand"],"hint_context":"The opposite of defend.","correct_answers":["attack"]},{"id":"gap-2","text":"''When we lose it — ___ their midfielder immediately!''","context":"Close down the opponent fast","options":["press","watch","greet","clap"],"hint_context":"Put them under immediate pressure.","correct_answers":["press"]}],"xp_reward":25},{"id":"step-9","type":"memory_match","title":"Coach''s commands review","xp_reward":60,"vocabulary":[{"en":"Pass","id":1,"pt":"Passar","enImage":"","ptImage":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/commands/pass.png"},{"en":"Shoot","id":2,"pt":"Chutar ao gol","enImage":"","ptImage":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/commands/shoot.png"},{"en":"Cross","id":3,"pt":"Cruzar","enImage":"","ptImage":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/commands/cross.png"},{"en":"Attack","id":4,"pt":"Atacar","enImage":"","ptImage":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/vocab/attack.png"},{"en":"Defend","id":5,"pt":"Defender","enImage":"","ptImage":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/vocab/defence.png"},{"en":"Press","id":6,"pt":"Pressionar","enImage":"","ptImage":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/vocab/press.png"},{"en":"Run","id":7,"pt":"Correr","enImage":"","ptImage":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/commands/run.png"}],"display_mode":"image"},{"id":"step-10","type":"completion","title":"Coachable","content":"You''ve decoded the eight commands a coach uses more than any others. Combined with the pass challenges you completed live, you can now react to what the coach shouts as it happens — not translate it half a second late. That''s the difference between a trialist who stays and one who goes home.","xp_reward":140,"achievements":["✅ Four ball commands learned","✅ Four movement commands mastered","✅ Seven live pass commands followed","✅ Ready for a training-ground drill in English"],"badge_unlocked":"Coachable","next_lesson_preview":"Unit 1 complete — the Training Centre radar now shows 25% across all six skills. Next up: Unit 2 — The Signing.","translation_available":true}],"session":5,"difficulty":"A1","skill_area":"coach"}', null, null, null, true, 5, '2026-08-13 22:45:41.119594+00', '2026-08-13 22:45:41.119594+00', null, null, null, null, 1, 5, null, null, false, 'players', false, 'propath_26_27', ARRAY['coach']), ('f5282260-612f-4f26-9565-b8b417ef7dca', '6. Daily Life: At the Canteen', null, 101, 'Beginner', 100, '{"type":"multi_step","unit":1,"steps":[{"id":"step-1","type":"scenario","title":"6. At the Canteen","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/scenarios/canteen.png"},{"id":"step-2","type":"vocabulary","title":"Drinks","content":"You''ve finished training. You''re thirsty. The canteen has everything. Five drinks to know — this is the first English you''ll speak every day.","vocabulary":[{"english":"water","example":"A bottle of water, please.","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/daily-life/water.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/daily-life/water.png","usage_tip":"The most important word on this page. Ask for water twenty times a day if you need to.","translation":"água","pronunciation":"/ˈwɔːtə/"},{"english":"juice","example":"I''d like an orange juice.","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/daily-life/juice.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/daily-life/juice.png","usage_tip":"Common types: orange juice, apple juice. The type comes first.","translation":"suco","pronunciation":"/dʒuːs/"},{"english":"milk","example":"Can I have milk with my coffee?","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/daily-life/milk.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/daily-life/milk.png","usage_tip":"Great post-training — the protein helps recovery. British canteens serve tea with milk by default.","translation":"leite","pronunciation":"/mɪlk/"},{"english":"coffee","example":"One coffee, please.","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/daily-life/coffee.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/daily-life/coffee.png","usage_tip":"European football clubs run on coffee. Ask for it black (''black coffee'') or with milk (''coffee with milk'').","translation":"café","pronunciation":"/ˈkɒfi/"},{"english":"tea","example":"A cup of tea, please.","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/daily-life/tea.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/daily-life/tea.png","usage_tip":"British football''s fuel. Nine times out of ten it comes with milk unless you say otherwise.","translation":"chá","pronunciation":"/tiː/"}]},{"id":"step-3","type":"drag_drop_vocab","title":"Match the drink","content":"Drag each word onto the matching picture.","xp_reward":30,"vocab_config":{"items":[{"id":"d-water","english":"Water","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/daily-life/water.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/daily-life/water.png","translation":"Água"},{"id":"d-juice","english":"Juice","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/daily-life/juice.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/daily-life/juice.png","translation":"Suco"},{"id":"d-milk","english":"Milk","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/daily-life/milk.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/daily-life/milk.png","translation":"Leite"},{"id":"d-coffee","english":"Coffee","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/daily-life/coffee.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/daily-life/coffee.png","translation":"Café"},{"id":"d-tea","english":"Tea","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/daily-life/tea.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/daily-life/tea.png","translation":"Chá"}],"display_mode":"image"}},{"id":"step-4","type":"vocabulary","title":"Post-training food","content":"You''ve burned two thousand calories in training. Five foods every football canteen in the world serves.","vocabulary":[{"english":"pasta","example":"Chicken and pasta, please.","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/daily-life/pasta.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/daily-life/pasta.png","usage_tip":"The classic post-training carb. Every pro football canteen from São Paulo to Manchester serves it.","translation":"macarrão / massa","pronunciation":"/ˈpæstə/"},{"english":"chicken","example":"I''d like the chicken, please.","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/daily-life/chicken.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/daily-life/chicken.png","usage_tip":"The go-to protein. Lean, safe for training, easy to digest.","translation":"frango","pronunciation":"/ˈtʃɪkɪn/"},{"english":"rice","example":"Chicken with rice, please.","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/daily-life/rice.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/daily-life/rice.png","usage_tip":"The alternative to pasta. Brazilians will feel at home.","translation":"arroz","pronunciation":"/raɪs/"},{"english":"salad","example":"A green salad on the side.","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/daily-life/salad.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/daily-life/salad.png","usage_tip":"Always eat some. Fitness coaches watch what you put on your plate — vegetables count.","translation":"salada","pronunciation":"/ˈsæləd/"},{"english":"fruit","example":"Can I have some fruit?","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/daily-life/fruit.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/daily-life/fruit.png","usage_tip":"General word — apples, bananas, oranges, all count. ''A piece of fruit'' or just ''some fruit''.","translation":"fruta","pronunciation":"/fruːt/"}]},{"id":"step-5","type":"drag_drop_vocab","title":"Match the food","content":"Drag each word onto the matching picture.","xp_reward":30,"vocab_config":{"items":[{"id":"f-pasta","english":"Pasta","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/daily-life/pasta.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/daily-life/pasta.png","translation":"Massa"},{"id":"f-chicken","english":"Chicken","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/daily-life/chicken.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/daily-life/chicken.png","translation":"Frango"},{"id":"f-rice","english":"Rice","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/daily-life/rice.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/daily-life/rice.png","translation":"Arroz"},{"id":"f-salad","english":"Salad","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/daily-life/salad.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/daily-life/salad.png","translation":"Salada"},{"id":"f-fruit","english":"Fruit","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/daily-life/fruit.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/daily-life/fruit.png","translation":"Fruta"}],"display_mode":"image"}},{"id":"step-6","type":"vocabulary","title":"How to order","content":"Four phrases and you can order anything, anywhere. The polite British ''please'' at the end is not optional — it''s what separates rude from respectful.","vocabulary":[{"english":"I''d like…","example":"I''d like the chicken, please.","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/daily-life/id-like.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/daily-life/id-like.png","usage_tip":"The go-to opening. Short for ''I would like''. Sounds polite, professional.","translation":"Eu queria… / Eu gostaria de…","pronunciation":"/aɪd laɪk/"},{"english":"Can I have…, please?","example":"Can I have a bottle of water, please?","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/daily-life/can-i-have.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/daily-life/can-i-have.png","usage_tip":"Even more common than ''I''d like''. Always end with ''please'' — it''s the difference between polite and rude in English.","translation":"Pode me dar… por favor?","pronunciation":"/kən aɪ hæv/"},{"english":"Yes, please.","example":"''Would you like more?'' — ''Yes, please.''","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/daily-life/yes-please.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/daily-life/yes-please.png","usage_tip":"Never just ''yes'' — always ''yes, please''. It''s short but it matters.","translation":"Sim, por favor.","pronunciation":"/jes pliːz/"},{"english":"No, thank you.","example":"''Would you like sugar?'' — ''No, thank you.''","audio_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Audios/pp/daily-life/no-thank-you.m4a","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/daily-life/no-thank-you.png","usage_tip":"Same rule — never just ''no''. ''No, thanks'' is the shorter, friendlier version between teammates.","translation":"Não, obrigado.","pronunciation":"/nəʊ θæŋk juː/"}]},{"id":"step-7","type":"ai_gap_fill","title":"Complete your order","content":"Fill in the gap.","image_url":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/scenarios/canteen.png","sentences":[{"id":"gap-1","text":"''___ I have the chicken with rice, please?''","context":"Ordering your main plate","options":["Can","Do","Am","Is"],"hint_context":"The polite way to ask for something.","correct_answers":["Can"]},{"id":"gap-2","text":"''Would you like some water?'' — ''Yes, ___.''","context":"Accepting politely","options":["please","yes","thanks","ok"],"hint_context":"The word that turns ''yes'' into a polite reply.","correct_answers":["please"]}],"xp_reward":25},{"id":"step-8","type":"ai_speech_practice","title":"Place your order","prompt":"","context":"At the canteen","xp_reward":30,"expectedText":"I''d like the chicken with rice, please. And a bottle of water. Thank you.","instructions":{"en":"Say it warmly and calmly. In a real canteen the server has ten other players waiting — clarity beats speed.","pt":"Diga com calma e simpatia. No refeitório de verdade, o servente tem dez outros jogadores esperando — clareza é melhor que pressa."}},{"id":"step-9","type":"memory_match","title":"Canteen review","xp_reward":60,"vocabulary":[{"en":"Water","id":1,"pt":"Água","enImage":"","ptImage":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/daily-life/water.png"},{"en":"Coffee","id":2,"pt":"Café","enImage":"","ptImage":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/daily-life/coffee.png"},{"en":"Chicken","id":3,"pt":"Frango","enImage":"","ptImage":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/daily-life/chicken.png"},{"en":"Pasta","id":4,"pt":"Massa","enImage":"","ptImage":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/daily-life/pasta.png"},{"en":"Fruit","id":5,"pt":"Fruta","enImage":"","ptImage":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/daily-life/fruit.png"},{"en":"I''d like…","id":6,"pt":"Eu queria…","enImage":"","ptImage":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/daily-life/id-like.png"},{"en":"Can I have…?","id":7,"pt":"Pode me dar…?","enImage":"","ptImage":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/daily-life/can-i-have.png"},{"en":"Yes, please.","id":8,"pt":"Sim, por favor.","enImage":"","ptImage":"https://ojxmpejjvwfaxtlmcnuq.supabase.co/storage/v1/object/public/Images/pp/daily-life/yes-please.png"}],"display_mode":"image"},{"id":"step-10","type":"completion","title":"Canteen Ready","content":"After every training session for the next twenty years, you''ll walk into a canteen. From today, you know how to order in English — clearly, politely, professionally. That''s Unit 1 complete. Six skills, twenty-five percent each on the Training Centre radar. Unit 2 unlocks next — welcome to The Signing.","xp_reward":140,"achievements":["✅ Five drinks and five foods learned","✅ Four ordering phrases mastered","✅ First canteen order placed in English","✅ Unit 1: The Trial — complete"],"badge_unlocked":"Canteen Ready","unit_completion":true,"next_lesson_preview":"Unit 2 — The Signing — starts with your first proper pitch calls.","translation_available":true}],"session":6,"difficulty":"A1","skill_area":"daily-life"}', null, null, null, true, 6, '2026-08-14 01:20:47.77237+00', '2026-08-14 01:20:47.77237+00', null, null, null, null, 1, 6, null, null, null, 'players', false, 'propath_26_27', ARRAY['daily_life']);